css:
.fx-cmp{width:min(820px,100%);position:relative;min-height:420px;border:1px solid var(--border);border-radius:var(--radius);overflow:hidden;background:var(--surface)}
.fx-cmp .grid{display:grid;grid-template-columns:repeat(4,1fr);gap:1em;padding:1.2em 1.2em 5.5em}
.fx-cmp .it{display:flex;flex-direction:column;gap:.5em;font-size:.92em}
.fx-cmp .it .fx-art{aspect-ratio:1;border-radius:calc(var(--radius)*.7)}
.fx-cmp .it label{display:flex;align-items:center;gap:.5em;cursor:pointer;font-weight:700;font-size:.85em}
.fx-cmp .it input{accent-color:var(--primary);width:1.1em;height:1.1em}
.fx-cmp .tray{position:absolute;left:0;right:0;bottom:0;display:flex;align-items:center;gap:1em;padding:.9em 1.2em;background:var(--primary);color:var(--on-primary);transform:translateY(100%);transition:transform calc(.4s/var(--speed)) cubic-bezier(.2,.8,.2,1)}
.fx-cmp .tray.on{transform:none}
.fx-cmp .tray .th{display:flex;gap:.5em;flex:1}
.fx-cmp .tray .th i{width:2.6em;aspect-ratio:1;border-radius:.5em;background:color-mix(in srgb,var(--on-primary) 25%,transparent);border:1px dashed color-mix(in srgb,var(--on-primary) 55%,transparent)}
.fx-cmp .tray .th i.f{background:var(--accent);border:0}
.fx-cmp .tray button{background:var(--accent);color:var(--on-accent);border:0;border-radius:99px;padding:.7em 1.4em;font:700 .95em var(--font-body);cursor:pointer}
.fx-cmp .tray button:disabled{opacity:.4;cursor:not-allowed}
@media(max-width:640px){.fx-cmp .grid{grid-template-columns:repeat(2,1fr)}}
@media(prefers-reduced-motion:reduce){.fx-cmp .tray{transition:none}}
